(() => {
'use strict';
const canvas=document.querySelector('#world'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let W=0,H=0,dpr=1,camera={x:0,y:0},last=performance.now(),running=false,paused=false,gameTime=6.7,toastTimer=0,audioCtx=null;
const world={w:2600,h:1900};
let player={x:380,y:980,hp:100,food:82,water:67,rad:3,stamina:100,ammo:18,reserve:72,weight:14,rep:0,coins:31,bandages:2};
let inventory=[{name:'AKM de servicio',type:'Arma',qty:1,detail:'7.62 × 39 mm · condición 84%'},{name:'Munición 7.62',type:'Munición',qty:90,detail:'Para el AKM'},{name:'Botella de agua',type:'Consumible',qty:2,detail:'Restaura 32 de sed',action:'water'},{name:'Ración seca',type:'Consumible',qty:2,detail:'Restaura 28 de hambre',action:'food'},{name:'Botiquín',type:'Medicina',qty:2,detail:'Restaura 45 de salud',action:'med'},{name:'Detector Echo',type:'Equipo',qty:1,detail:'Señala anomalías cercanas'},{name:'Vendaje',type:'Medicina',qty:2,detail:'Frena el sangrado',action:'med'}];
let quest={stage:0,done:[],active:'La señal del norte'};
const zones=[{name:'EL BORDE',x:0,y:0,w:800,h:1900,sector:'C-04 / PERÍMETRO'},{name:'PUEBLO DE DUBOV',x:800,y:0,w:760,h:1900,sector:'C-05 / DUBOV'},{name:'PLANTA VIEJA',x:1560,y:0,w:1040,h:1900,sector:'D-06 / PLANTA'}];
const buildings=[
 {x:270,y:570,w:155,h:100,type:'hut',name:'Puesto de guardia',loot:'Ración de campo',interact:'loot'}, {x:560,y:1230,w:155,h:115,type:'house',name:'Casa abandonada',loot:'Botella de agua',interact:'loot'},
 {x:990,y:520,w:160,h:125,type:'house',name:'Casa de la maestra',loot:'Botiquín',interact:'loot'}, {x:1305,y:1060,w:195,h:135,type:'house',name:'Tienda del pueblo',interact:'merchant'}, {x:930,y:1430,w:155,h:105,type:'hut',name:'Cobertizo',loot:'Munición 7.62',interact:'loot'},
 {x:1755,y:430,w:210,h:150,type:'factory',name:'Almacén 4',loot:'Munición 7.62',interact:'loot'}, {x:2110,y:950,w:235,h:175,type:'factory',name:'Laboratorio X-12',loot:'Artefacto: Ojo',interact:'artifact'}, {x:1770,y:1370,w:190,h:150,type:'hut',name:'Puesto de radio',loot:'Registro de Sokolov',interact:'radio'}
];
let props=[]; let seed=3471;function rnd(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
// Deliberate clearings around landmarks, with dense woodland at the map edges.
for(let i=0;i<350;i++){let x=rnd()*world.w,y=rnd()*world.h;if(buildings.some(b=>Math.abs(x-b.x)<b.w*.8&&Math.abs(y-b.y)<b.h*.9))continue;if(x>world.w*.3&&x<world.w*.72&&y>500&&y<1470&&rnd()<.72)continue;props.push({x,y,r:9+rnd()*14,type:rnd()<.84?'tree':'rock',tone:rnd()})}
const npcs=[{x:1120,y:920,name:'Sokolov',faction:'Vigías',color:'#b68b62',role:'guide',mood:0,baseX:1120,baseY:920},{x:1400,y:1130,name:'Mara',faction:'Mercaderes',color:'#80a18b',role:'merchant',mood:0,baseX:1400,baseY:1130},{x:790,y:1080,name:'Yuri',faction:'Vigías',color:'#8694a4',role:'guard',mood:0,baseX:790,baseY:1080},{x:1900,y:1030,name:'Mutante',faction:'Hostil',color:'#bd735c',role:'enemy',mood:0,baseX:1900,baseY:1030},{x:2070,y:1075,name:'Mutante',faction:'Hostil',color:'#bd735c',role:'enemy',mood:0,baseX:2070,baseY:1075}];
const lootObjects=[...buildings.filter(b=>b.interact).map((b,i)=>({x:b.x+b.w*.5,y:b.y+b.h+28,name:b.name,loot:b.loot,type:b.interact,used:false,building:b})),{x:690,y:770,name:'Alijo de cazador',loot:'Ración seca',type:'loot',used:false},{x:1500,y:720,name:'Detector roto',loot:'Detector de anomalías',type:'loot',used:false},{x:1930,y:730,name:'Campo de distorsión',loot:'Artefacto: Espina',type:'anomaly',used:false}];
const particles=[];let bullets=[];const keys={};
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=canvas.clientWidth;H=canvas.clientHeight;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',resize);resize();
function centerCam(){camera.x=clamp(player.x-W/2,0,world.w-W);camera.y=clamp(player.y-H/2,0,world.h-H)}
function screen(p){return{x:p.x-camera.x,y:p.y-camera.y}}
function playTone(freq=280,dur=.08,type='sine',vol=.025){try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch(e){}}
function notify(msg){const t=$('#toast');t.innerHTML=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}
function setQuest(title,text){$('#questTitle').textContent=title;$('#questText').textContent=text;quest.active=title}
function addItem(name,qty=1,detail='Recogido de la zona',action){let it=inventory.find(i=>i.name===name);if(it)it.qty+=qty;else inventory.push({name,type:'Objeto',qty,detail,action});player.weight+=qty*0.4;playTone(540,.1);notify(`<em>ADQUIRIDO</em> · ${name} ×${qty}`)}
function zoneAt(x,y){return zones.find(z=>x>=z.x&&x<z.x+z.w)||zones[0]}
function nearby(){let candidates=[...lootObjects.filter(o=>!o.used).map(o=>({...o,kind:'object'})),...npcs.map(o=>({...o,kind:'npc'}))];candidates.sort((a,b)=>dist(player,a)-dist(player,b));return candidates.find(o=>dist(player,o)<75)}
function startGame(load=false){$('#startscreen').style.display='none';running=true;paused=false;if(load&&localStorage.getItem('tierraSave')){try{const s=JSON.parse(localStorage.getItem('tierraSave'));Object.assign(player,s.player);inventory=s.inventory;quest=s.quest;gameTime=s.gameTime||6.7;notify('Partida restaurada · buena suerte ahí fuera.')}catch(e){}}else{saveGame()}last=performance.now();playTone(420,.18);requestAnimationFrame(loop)}
function saveGame(){try{localStorage.setItem('tierraSave',JSON.stringify({player,inventory,quest,gameTime,world:{npcs:npcs.map(n=>({x:n.x,y:n.y,mood:n.mood})),used:lootObjects.map(o=>o.used)}}));notify('Partida guardada en el PDA')}catch(e){}}
function interact(){const o=nearby();if(!o){notify('Nada cerca con lo que interactuar.');return}if(o.kind==='npc'){talk(o);return}const obj=lootObjects.find(x=>x.name===o.name);if(!obj)return;if(obj.type==='merchant'){openMerchant();return}if(obj.type==='radio'){if(quest.stage===0){obj.used=true;quest.stage=1;player.rep+=10;setQuest('El eco del laboratorio','Sokolov encontró un rastro en el laboratorio X-12. Busca el artefacto y vuelve al puesto de radio.');showDialog('Registro recuperado','La radio crepita. «...el detector está fallando. El artefacto sigue en X-12. No vengas sin protección...» Sokolov necesita que encuentres la señal.',[['Guardar registro',()=>{addItem('Registro de Sokolov');closeDialog()}]]);return}}
 if(obj.type==='artifact'){obj.used=true;addItem(obj.loot);player.rad+=7;quest.stage=Math.max(quest.stage,2);setQuest('Volver a Sokolov','Lleva el Ojo de anomalía al puesto de radio. La radiación está subiendo.');player.rep+=15;return}
 if(obj.type==='anomaly'){if(!inventory.some(i=>i.name==='Detector de anomalías')){notify('SEÑAL FUERTE · necesitas un detector para acercarte');return}player.rad+=3;obj.used=true;addItem(obj.loot);return}
 obj.used=true;addItem(obj.loot||'Suministros',1,obj.name);if(obj.name==='Alijo de cazador'){quest.stage=Math.max(quest.stage,0);setQuest('La señal del norte','Encuentra a Sokolov en el pueblo de Dubov. Busca la torre de radio al este.')} }
function talk(n){if(n.role==='enemy'){notify('HOSTIL DETECTADO · ESPACIO para disparar');return}if(n.role==='merchant'){openMerchant();return}if(n.role==='guide'){if(quest.stage===0){showDialog('Sokolov · Vigías','Llegaste. La torre está en el viejo puesto de radio, al este. Necesito que revises mi transmisión. Toma esto; te hará falta.',[['Aceptar la misión',()=>{addItem('Botella de agua');quest.stage=0;setQuest('La señal del norte','Encuentra la señal en el puesto de radio abandonado. Está al este del pueblo.');player.rep+=5;closeDialog()}],['Preguntar por la zona',()=>{showDialog('Sokolov · Vigías','Dubov comercia si Mara está de buen humor. No cruces el campo azul sin un detector; los artefactos valen más que la vida, según algunos.',[['Entendido',closeDialog]])}]]);return}if(quest.stage===2){showDialog('Sokolov · Vigías','Ese brillo... sí, es el Ojo. Buen trabajo. Los Vigías no olvidan quién ayuda.',[['Entregar artefacto · +60 fichas',()=>{let i=inventory.find(x=>x.name==='Artefacto: Ojo');if(i){i.qty--;if(!i.qty)inventory=inventory.filter(x=>x!==i)}player.coins+=60;player.rep+=25;quest.stage=3;quest.done.push('La señal del norte');setQuest('Deuda pagada','Ayuda a los habitantes de Dubov o explora la Planta Vieja.');closeDialog();notify('MISIÓN COMPLETADA · reputación +25')}]]);return}showDialog('Sokolov · Vigías',quest.stage>=3?'Mantente vivo ahí fuera. La zona cambia con cada emisión.':'Todavía no tenemos una señal clara. Revisa el puesto de radio al este.',[['Cerrar',closeDialog]])}else showDialog(n.name+' · '+n.faction,'¿Qué necesitas, caminante? Hay cosas que es mejor no preguntar en voz alta.',[['Preguntar por rumores',()=>{player.rep+=1;closeDialog();notify('«Hay un alijo cerca del borde, junto a la línea de árboles.»')}],['Cerrar',closeDialog]])}
function showDialog(title,text,buttons=[]){$('#dialogTitle').textContent=title;$('#dialogText').textContent=text;const el=$('#dialogButtons');el.innerHTML='';buttons.forEach(([label,fn])=>{let b=document.createElement('button');b.className='primary';b.textContent=label;b.onclick=fn;el.appendChild(b)});$('#dialog').classList.add('open')}
function closeDialog(){$('#dialog').classList.remove('open')}
function openMerchant(){showDialog('Mara · Mercado de Dubov',`«El cambio está en ${price('agua')} fichas por agua. Precios cambian con el clima.» Tienes ${player.coins} fichas.`,[['Comprar agua · '+price('agua'),()=>buy('Botella de agua',price('agua'),'water')],['Comprar ración · '+price('food'),()=>buy('Ración seca',price('food'),'food')],['Vender chatarra · +12',()=>{player.coins+=12;addItem('Chatarra',-1);inventory=inventory.filter(i=>i.qty>0);closeDialog()}],['Salir',closeDialog]])}
function price(kind){return kind==='agua'?(player.water<30?8:12):player.food<30?10:14}
function buy(name,cost,action){if(player.coins<cost){notify('Fichas insuficientes');return}player.coins-=cost;addItem(name,1,'Compra del mercado',action);closeDialog()}

function panelOpen(which){paused=true;const p=$('#panel');p.classList.add('open');renderPanel(which)}
function renderPanel(which){const tabs=$('#tabs'),content=$('#panelContent');tabs.innerHTML='';const menu=[['map','MAPA'],['inventory','INVENTARIO'],['journal','DIARIO'],['status','ESTADO']];menu.forEach(([id,label])=>{let b=document.createElement('button');b.className='tab '+(id===which?'active':'');b.textContent=label;b.onclick=()=>renderPanel(id);tabs.appendChild(b)});
if(which==='map'){$('#panelTitle').textContent='MAPA DE ZONA';content.innerHTML=`<div class="mapbox"><span class="maplabel" style="left:9%;top:40%">EL BORDE</span><span class="maplabel" style="left:39%;top:38%">DUBOV</span><span class="maplabel" style="left:70%;top:37%">PLANTA VIEJA</span><span class="maplabel" style="left:75%;top:69%;color:#e77b63">☢ ANOMALÍA</span><span class="maplabel" style="left:46%;top:69%">PUESTO DE RADIO</span><i class="marker" style="left:${clamp(player.x/world.w*100,2,96)}%;top:${clamp(player.y/world.h*100,4,94)}%"></i></div><div class="row"><span>▣ Posición actual</span><b>${zoneAt(player.x,player.y).sector}</b></div><div class="row"><span>◉ Objetivo</span><b>${quest.active}</b></div><p>Territorio Vigías · Dubov y el perímetro. Presencia hostil confirmada en la Planta Vieja. La anomalía emite pulsos cada pocos minutos.</p>`}
if(which==='inventory'){$('#panelTitle').textContent='EQUIPO & RECURSOS';let cells=inventory.map((it,i)=>`<div class="item"><strong>${it.name}</strong><small>${it.type} · ×${it.qty}<br>${it.detail||''}</small>${it.action&&it.qty>0?`<button onclick="useItem(${i})">USAR</button>`:''}</div>`).join('');content.innerHTML=`<div class="row"><span>CAPACIDAD DE CARGA</span><b>${player.weight.toFixed(1)} / 32 kg</b></div><div class="itemgrid">${cells}</div><div class="row"><span>Fichas de trueque</span><b>◈ ${player.coins}</b></div><p>Los consumibles también se pueden usar desde el inventario. La carga elevada reduce la velocidad.</p>`}
if(which==='journal'){$('#panelTitle').textContent='DIARIO DE CAMPO';let done=quest.done.map(t=>`<div class="row"><span>✓ ${t}</span><b>COMPLETADA</b></div>`).join('');content.innerHTML=`<div class="eyebrow">PRINCIPAL · ${quest.stage>=3?'COMPLETADA':'EN CURSO'}</div><h3 style="font:600 23px 'Barlow Condensed';margin:7px 0">${quest.active}</h3><p>${$('#questText').textContent}</p><div class="row"><span>1 · Sigue la señal de radio</span><b>${quest.stage>0?'✓':'…'}</b></div><div class="row"><span>2 · Explora el laboratorio X-12</span><b>${quest.stage>1?'✓':'—'}</b></div><div class="row"><span>3 · Regresa con Sokolov</span><b>${quest.stage>2?'✓':'—'}</b></div>${done}<hr style="border-color:#ffffff20"><div class="eyebrow">FACCIÓN · VIGÍAS</div><div class="row"><span>Reputación</span><b>${player.rep} · ${player.rep>30?'Aliado':'Neutral'}</b></div><p>Los Vigías protegen a los habitantes de Dubov. Los Mercaderes valoran los artefactos y los suministros médicos.</p>`}
if(which==='status'){$('#panelTitle').textContent='ESTADO DEL SUPERVIVIENTE';content.innerHTML=`<div class="row"><span>Salud</span><b>${Math.round(player.hp)}%</b></div><div class="row"><span>Hambre / Sed</span><b>${Math.round(player.food)}% / ${Math.round(player.water)}%</b></div><div class="row"><span>Radiación acumulada</span><b>${Math.round(player.rad)} mSv</b></div><div class="row"><span>Munición</span><b>${player.ammo} + ${player.reserve}</b></div><div class="row"><span>Relaciones</span><b>Vigías ${player.rep} · Mercaderes 0</b></div><p>La fatiga aumenta al correr. Descansa en un lugar seguro. La lluvia y la niebla pueden cambiar la visibilidad y la actividad de las anomalías.</p><button class="primary" onclick="saveGame()">GUARDAR PARTIDA</button>`}}
function closePanel(){ $('#panel').classList.remove('open');paused=false;last=performance.now()}
window.useItem=function(i){const it=inventory[i];if(!it||!it.qty)return;if(it.action==='food'){player.food=clamp(player.food+28,0,100);consumeItem(it)}else if(it.action==='water'){player.water=clamp(player.water+32,0,100);consumeItem(it)}else if(it.action==='med'){player.hp=clamp(player.hp+45,0,100);consumeItem(it)}updateHud();renderPanel('inventory')};function consumeItem(it){it.qty--;if(it.qty<=0)inventory=inventory.filter(x=>x!==it);playTone(360,.12);notify(`${it.name} usado`)}
function drawGround(){ctx.fillStyle='#28382e';ctx.fillRect(0,0,W,H);const sx=camera.x,sy=camera.y;for(let x=Math.floor(sx/70)*70;x<sx+W+70;x+=70)for(let y=Math.floor(sy/70)*70;y<sy+H+70;y+=70){const n=Math.sin(x*12.98+y*4.14)*43758.5;ctx.fillStyle=n%1>.5?'#2a3a2f':'#29382e';ctx.fillRect(x-sx,y-sy,70,70)}
// overgrown dirt tracks joining all sectors
ctx.save();ctx.translate(-sx,-sy);ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#756f50';ctx.lineWidth=86;ctx.beginPath();ctx.moveTo(-100,1010);ctx.bezierCurveTo(450,900,520,1120,900,980);ctx.bezierCurveTo(1300,850,1320,670,1780,850);ctx.bezierCurveTo(2100,980,2270,880,2700,790);ctx.stroke();ctx.strokeStyle='#96906b';ctx.lineWidth=3;ctx.setLineDash([17,24]);ctx.beginPath();ctx.moveTo(-100,1010);ctx.bezierCurveTo(450,900,520,1120,900,980);ctx.bezierCurveTo(1300,850,1320,670,1780,850);ctx.bezierCurveTo(2100,980,2270,880,2700,790);ctx.stroke();ctx.setLineDash([]);ctx.restore();
// wet marsh and irradiated ground
ctx.save();ctx.translate(-sx,-sy);ctx.fillStyle='#40524699';for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse(850+i*90,1600-i*42,150,60,-.2,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#63894b1c';ctx.beginPath();ctx.ellipse(1940,740,260,180,.2,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawBuilding(b){let x=b.x-camera.x,y=b.y-camera.y;if(x<-260||x>W+260||y<-220||y>H+220)return;ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(x+b.w/2,y+b.h+10,b.w*.7,15,0,0,Math.PI*2);ctx.fill();if(b.type==='factory'){ctx.fillStyle='#5e6256';ctx.fillRect(x,y,b.w,b.h);ctx.fillStyle='#77786a';ctx.fillRect(x-6,y-9,b.w+10,18);ctx.fillStyle='#444b44';ctx.fillRect(x+12,y+19,40,40);ctx.fillRect(x+b.w-54,y+19,38,40);ctx.fillStyle='#a86448';ctx.fillRect(x+b.w*.48,y-40,25,40);ctx.fillStyle='#2d382f';ctx.fillRect(x+70,y+b.h-45,54,45)}else{ctx.fillStyle='#454a3f';ctx.fillRect(x,y+30,b.w,b.h-30);ctx.fillStyle=b.type==='hut'?'#565347':'#665947';ctx.beginPath();ctx.moveTo(x-12,y+38);ctx.lineTo(x+b.w*.5,y-14);ctx.lineTo(x+b.w+12,y+38);ctx.closePath();ctx.fill();ctx.fillStyle='#252d28';ctx.fillRect(x+b.w*.17,y+53,33,27);ctx.fillRect(x+b.w*.67,y+53,27,27);ctx.fillStyle='#302c25';ctx.fillRect(x+b.w*.43,y+b.h-43,34,43)}
ctx.strokeStyle='#c9c4aa33';ctx.lineWidth=1;ctx.strokeRect(x,y+30,b.w,b.h-30)}
function drawProps(){for(const p of props){const x=p.x-camera.x,y=p.y-camera.y;if(x<-60||x>W+60||y<-70||y>H+50)continue;if(p.type==='tree'){ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(x+8,y+12,p.r*1.1,p.r*.48,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#514336';ctx.fillRect(x-3,y-1,7,18);let c=p.tone>.5?'#374c37':'#3e513a';ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y-p.r*.35,p.r,0,Math.PI*2);ctx.fill();ctx.fillStyle=p.tone>.5?'#4b6245':'#506447';ctx.beginPath();ctx.arc(x-p.r*.28,y-p.r*.58,p.r*.66,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffffff0b';ctx.beginPath();ctx.arc(x-p.r*.25,y-p.r*.8,p.r*.32,0,Math.PI*2);ctx.fill()}else{ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(x+4,y+6,p.r,p.r*.45,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#696d61';ctx.beginPath();ctx.ellipse(x,y,p.r,p.r*.68,-.3,0,Math.PI*2);ctx.fill()}}}
function drawObject(o){const x=o.x-camera.x,y=o.y-camera.y;if(x<-40||x>W+40||y<-40||y>H+40)return;if(o.type==='anomaly'){let pulse=(Math.sin(performance.now()/400)+1)*.5;ctx.save();ctx.translate(x,y);ctx.strokeStyle=`rgba(152,206,113,${.35+pulse*.5})`;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,0,28+pulse*10,13+pulse*5,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#d4ef76';ctx.fillRect(-2,-2,4,4);ctx.restore()}else{ctx.fillStyle='#d4ef76';ctx.fillRect(x-5,y-5,10,10);ctx.strokeStyle='#d4ef76';ctx.strokeRect(x-8,y-8,16,16)}}
function drawActor(a,isPlayer=false){const x=a.x-camera.x,y=a.y-camera.y;if(x<-70||x>W+70||y<-70||y>H+70)return;ctx.fillStyle='#0008';ctx.beginPath();ctx.ellipse(x,y+11,11,5,0,0,Math.PI*2);ctx.fill();if(a.role==='enemy'){ctx.fillStyle='#705044';ctx.beginPath();ctx.ellipse(x,y,13,9,.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d47859';ctx.beginPath();ctx.arc(x+5,y-3,3,0,Math.PI*2);ctx.fill();return}ctx.fillStyle=isPlayer?'#b8b8a0':a.color;ctx.fillRect(x-7,y-10,14,16);ctx.fillStyle='#b49a7d';ctx.beginPath();ctx.arc(x,y-14,6,0,Math.PI*2);ctx.fill();ctx.fillStyle=isPlayer?'#353b31':'#373d36';ctx.fillRect(x-8,y-2,16,6);if(isPlayer){ctx.fillStyle='#181d19';ctx.fillRect(x-3,y-3,20,3);ctx.fillStyle='#d4ef76';ctx.fillRect(x-2,y-19,4,3)}else if(dist(player,a)<150){ctx.fillStyle='#ecebdb';ctx.font='10px IBM Plex Mono';ctx.textAlign='center';ctx.fillText(a.name,x,y-27)}}
function drawBullets(){for(const b of bullets){const x=b.x-camera.x,y=b.y-camera.y;ctx.fillStyle='#ffd38b';ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill()}}
function drawFog(){let hour=gameTime%24,dark=hour<5.5||hour>19;ctx.fillStyle=dark?'rgba(8,15,15,.47)':(hour<7.5||hour>17?'rgba(178,165,124,.12)':'rgba(170,179,161,.06)');ctx.fillRect(0,0,W,H);let r=ctx.createRadialGradient(W/2,H/2,80,W/2,H/2,Math.max(W,H)*.8);r.addColorStop(0,'transparent');r.addColorStop(1,dark?'rgba(3,8,8,.35)':'rgba(11,17,14,.18)');ctx.fillStyle=r;ctx.fillRect(0,0,W,H)}
function render(){centerCam();drawGround();buildings.forEach(drawBuilding);drawProps();lootObjects.filter(o=>!o.used).forEach(drawObject);npcs.forEach(n=>drawActor(n));drawBullets();drawActor(player,true);drawFog();const z=zoneAt(player.x,player.y);$('#zoneName').textContent=z.name;$('#sector').textContent=z.sector;const near=nearby();$('#hint').innerHTML=near?`<kbd>E</kbd> INTERACTUAR · ${near.name.toUpperCase()}`:`<kbd>W A S D</kbd> MOVER &nbsp;·&nbsp; <kbd>E</kbd> INTERACTUAR &nbsp;·&nbsp; <kbd>ESPACIO</kbd> DISPARAR`;$('#hint').classList.toggle('interact',false)}

