function blocked(x,y){if(x<12||y<12||x>world.w-12||y>world.h-12)return true;return buildings.some(b=>x>b.x-12&&x<b.x+b.w+12&&y>b.y+8&&y<b.y+b.h)}
function shoot(){if(fireCooldown>0)return;if(player.ammo<=0){notify('Sin munición cargada. Pulsa R para recargar.');return}player.ammo--;fireCooldown=.38;playTone(110,.09,'sawtooth',.045);let target=npcs.filter(n=>n.role==='enemy').sort((a,b)=>dist(player,a)-dist(player,b))[0];let dx=target?target.x-player.x:Math.cos(aimAngle)*250,dy=target?target.y-player.y:Math.sin(aimAngle)*250;let d=Math.hypot(dx,dy)||1;bullets.push({x:player.x,y:player.y-3,vx:dx/d*570,vy:dy/d*570,life:1.1});}
