let anomaly=lootObjects.find(o=>o.type==='anomaly'&&!o.used);if(anomaly&&dist(player,anomaly)<100&&inventory.some(i=>i.name==='Detector de anomalías'))player.rad=clamp(player.rad+dt*.45,0,100);if(Math.random()<dt*.001)storm=!storm;if(player.hp<=0){player.hp=35;player.x=420;player.y=980;player.coins=Math.max(0,player.coins-10);notify('DESMAYO · despertaste en el perímetro. Perdiste 10 fichas.')}updateHud()}
