canvas.addEventListener('pointermove',e=>{const rect=canvas.getBoundingClientRect();aimAngle=Math.atan2(e.clientY-rect.top-H/2,e.clientX-rect.left-W/2)});canvas.addEventListener('pointerdown',e=>{if(running&&e.pointerType==='mouse')shoot()});
