const joyEl=$('#joystick'),stick=$('#stick');let joyPointer=null;joyEl.addEventListener('pointerdown',e=>{joyPointer=e.pointerId;joyEl.setPointerCapture(joyPointer);moveJoy(e)});joyEl.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)moveJoy(e)});function moveJoy(e){let r=joyEl.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),max=35,l=Math.hypot(dx,dy);if(l>max){dx*=max/l;dy*=max/l}joy.x=dx/max;joy.y=dy/max;stick.style.transform=`translate(${dx}px,${dy}px)`}joyEl.addEventListener('pointerup',releaseJoy);joyEl.addEventListener('pointercancel',releaseJoy);function releaseJoy(){joyPointer=null;joy.x=joy.y=0;stick.style.transform=''}
setInterval(()=>{if(running&&!paused)saveGame()},30000);
// Show an inviting preview scene before the expedition begins.
render();updateHud();
})();

