(()=>{'use strict';
const $=s=>document.querySelector(s),canvas=$('#world'),ctx=canvas.getContext('2d'),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let W=0,H=0,dpr=1,camera={x:0,y:0},last=performance.now(),running=false,paused=false,gameTime=6.7,toastTimer=0,audioCtx,storm=false,aimAngle=0,fireCooldown=0,steps=0,joy={x:0,y:0};
const world={w:2600,h:1900},keys={},zones=[{name:'EL BORDE',x:0,w:800,sector:'C-04 / PERÍMETRO'},{name:'PUEBLO DE DUBOV',x:800,w:760,sector:'C-05 / DUBOV'},{name:'PLANTA VIEJA',x:1560,w:1040,sector:'D-06 / PLANTA'}];
let player={x:380,y:980,hp:100,food:82,water:67,rad:3,stamina:100,ammo:18,reserve:72,weight:14,rep:0,coins:31};
let inventory=[{name:'AKM de servicio',type:'Arma',qty:1,detail:'7.62 × 39 mm · condición 84%'},{name:'Munición 7.62',type:'Munición',qty:90,detail:'Para el AKM'},{name:'Botella de agua',type:'Consumible',qty:2,detail:'Restaura 32 de sed',action:'water'},{name:'Ración seca',type:'Consumible',qty:2,detail:'Restaura 28 de hambre',action:'food'},{name:'Botiquín',type:'Medicina',qty:2,detail:'Restaura 45 de salud',action:'med'},{name:'Detector Echo',type:'Equipo',qty:1,detail:'Señala anomalías cercanas'},{name:'Vendaje',type:'Medicina',qty:2,detail:'Frena el sangrado',action:'med'}],quest={stage:0,done:[],active:'La señal del norte'};
const buildings=[{x:270,y:570,w:155,h:100,type:'hut',name:'Puesto de guardia',loot:'Ración de campo',interact:'loot'},{x:560,y:1230,w:155,h:115,type:'house',name:'Casa abandonada',loot:'Botella de agua',interact:'loot'},{x:990,y:520,w:160,h:125,type:'house',name:'Casa de la maestra',loot:'Botiquín',interact:'loot'},{x:1305,y:1060,w:195,h:135,type:'house',name:'Tienda del pueblo',interact:'merchant'},{x:930,y:1430,w:155,h:105,type:'hut',name:'Cobertizo',loot:'Munición 7.62',interact:'loot'},{x:1755,y:430,w:210,h:150,type:'factory',name:'Almacén 4',loot:'Munición 7.62',interact:'loot'},{x:2110,y:950,w:235,h:175,type:'factory',name:'Laboratorio X-12',loot:'Artefacto: Ojo',interact:'artifact'},{x:1770,y:1370,w:190,h:150,type:'hut',name:'Puesto de radio',loot:'Registro de Sokolov',interact:'radio'}];
let seed=3471;function rnd(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}let props=[];for(let i=0;i<350;i++){let x=rnd()*world.w,y=rnd()*world.h;if(buildings.some(b=>Math.abs(x-b.x)<b.w*.8&&Math.abs(y-b.y)<b.h*.9))continue;if(x>780&&x<1880&&y>500&&y<1470&&rnd()<.72)continue;props.push({x,y,r:9+rnd()*14,type:rnd()<.84?'tree':'rock',tone:rnd()})}
const npcs=[{x:1120,y:920,name:'Sokolov',faction:'Vigías',color:'#b68b62',role:'guide',baseX:1120,baseY:920},{x:1400,y:1130,name:'Mara',faction:'Mercaderes',color:'#80a18b',role:'merchant',baseX:1400,baseY:1130},{x:790,y:1080,name:'Yuri',faction:'Vigías',color:'#8694a4',role:'guard',baseX:790,baseY:1080},{x:1900,y:1030,name:'Mutante',faction:'Hostil',color:'#bd735c',role:'enemy',baseX:1900,baseY:1030},{x:2070,y:1075,name:'Mutante',faction:'Hostil',color:'#bd735c',role:'enemy',baseX:2070,baseY:1075}];
const lootObjects=[...buildings.filter(b=>b.interact).map(b=>({x:b.x+b.w*.5,y:b.y+b.h+28,name:b.name,loot:b.loot,type:b.interact,used:false})),{x:690,y:770,name:'Alijo de cazador',loot:'Ración seca',type:'loot',used:false},{x:1500,y:720,name:'Detector roto',loot:'Detector de anomalías',type:'loot',used:false},{x:1930,y:730,name:'Campo de distorsión',loot:'Artefacto: Espina',type:'anomaly',used:false}],bullets=[];
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=canvas.clientWidth;H=canvas.clientHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function playTone(freq=280,dur=.08,type='sine',vol=.025){try{audioCtx=audioCtx||new(window.AudioContext||window.webkitAudioContext)();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch(e){}}
function notify(msg){let t=$('#toast');t.innerHTML=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}function setQuest(title,text){$('#questTitle').textContent=title;$('#questText').textContent=text;quest.active=title}function addItem(name,qty=1,detail='Recogido de la zona',action){let it=inventory.find(i=>i.name===name);if(it)it.qty+=qty;else inventory.push({name,type:'Objeto',qty,detail,action});player.weight+=qty*.4;playTone(540,.1);notify(`<em>ADQUIRIDO</em> · ${name} ×${qty}`)}function zoneAt(x){return zones.find(z=>x>=z.x&&x<z.x+z.w)||zones[0]}
