function startGame(load=false){$('#startscreen').style.display='none';running=true;if(load){try{let s=JSON.parse(localStorage.getItem('tierraSave'));if(s){Object.assign(player,s.player);inventory=s.inventory;quest=s.quest;gameTime=s.gameTime||6.7;s.used?.forEach((v,i)=>{if(lootObjects[i])lootObjects[i].used=v});notify('Partida restaurada · buena suerte ahí fuera.')}}catch(e){}}last=performance.now();playTone(420,.18);requestAnimationFrame(loop)}
function saveGame(){try{localStorage.setItem('tierraSave',JSON.stringify({player,inventory,quest,gameTime,used:lootObjects.map(o=>o.used)}));notify('Partida guardada en el PDA')}catch(e){}}
function showDialog(title,text,buttons=[]){$('#dialogTitle').textContent=title;$('#dialogText').textContent=text;let el=$('#dialogButtons');el.innerHTML='';buttons.forEach(([label,fn])=>{let b=document.createElement('button');b.className='primary';b.textContent=label;b.onclick=fn;el.appendChild(b)});$('#dialog').classList.add('open')}function closeDialog(){$('#dialog').classList.remove('open')}
function interact(){let o=near();if(!o){notify('Nada cerca con lo que interactuar.');return}if(o.kind==='npc'){talk(o);return}let obj=lootObjects.find(x=>x.name===o.name);if(!obj)return;if(obj.type==='merchant'){openMerchant();return}if(obj.type==='radio'){if(quest.stage===0){obj.used=true;quest.stage=1;player.rep+=10;setQuest('El eco del laboratorio','Sokolov encontró un rastro en el laboratorio X-12. Busca el artefacto y vuelve al puesto de radio.');showDialog('Registro recuperado','La radio crepita. «...el detector está fallando. El artefacto sigue en X-12. No vengas sin protección...» Sokolov necesita que encuentres la señal.',[['Guardar registro',()=>{addItem('Registro de Sokolov');closeDialog()}]]);return}}
if(obj.type==='artifact'){obj.used=true;addItem(obj.loot);player.rad+=7;quest.stage=Math.max(quest.stage,2);setQuest('Volver a Sokolov','Lleva el Ojo de anomalía al puesto de radio. La radiación está subiendo.');player.rep+=15;return}if(obj.type==='anomaly'){if(!inventory.some(i=>i.name==='Detector de anomalías')){notify('SEÑAL FUERTE · necesitas un detector para acercarte');return}player.rad+=3;obj.used=true;addItem(obj.loot);return}obj.used=true;addItem(obj.loot||'Suministros');if(obj.name==='Alijo de cazador')setQuest('La señal del norte','Encuentra a Sokolov en el pueblo de Dubov. Busca la torre de radio al este.')}
