function near(){let all=[...lootObjects.filter(o=>!o.used).map(o=>({...o,kind:'object'})),...npcs.map(o=>({...o,kind:'npc'}))];all.sort((a,b)=>dist(player,a)-dist(player,b));return all.find(o=>dist(player,o)<75)}
function panelOpen(which){paused=true;$('#panel').classList.add('open');renderPanel(which)}function renderPanel(which){let tabs=$('#tabs'),c=$('#panelContent');tabs.innerHTML='';[['map','MAPA'],['inventory','INVENTARIO'],['journal','DIARIO'],['status','ESTADO']].forEach(([id,label])=>{let b=document.createElement('button');b.className='tab '+(id===which?'active':'');b.textContent=label;b.onclick=()=>renderPanel(id);tabs.appendChild(b)});if(which==='map'){$('#panelTitle').textContent='MAPA DE ZONA';c.innerHTML=`<div class="mapbox"><span class="maplabel" style="left:9%;top:40%">EL BORDE</span><span class="maplabel" style="left:39%;top:38%">DUBOV</span><span class="maplabel" style="left:70%;top:37%">PLANTA VIEJA</span><span class="maplabel" style="left:75%;top:69%;color:#e77b63">☢ ANOMALÍA</span><span class="maplabel" style="left:46%;top:69%">PUESTO DE RADIO</span><i class="marker" style="left:${clamp(player.x/world.w*100,2,96)}%;top:${clamp(player.y/world.h*100,4,94)}%"></i></div><div class="row"><span>▣ Posición actual</span><b>${zoneAt(player.x).sector}</b></div><div class="row"><span>◉ Objetivo</span><b>${quest.active}</b></div><p>Vigías mantienen el perímetro. Presencia hostil confirmada en la Planta Vieja.</p>`}if(which==='inventory'){$('#panelTitle').textContent='EQUIPO & RECURSOS';c.innerHTML=`<div class="row"><span>CAPACIDAD DE CARGA</span><b>${player.weight.toFixed(1)} / 32 kg</b></div><div class="itemgrid">${inventory.map((it,i)=>`<div class="item"><strong>${it.name}</strong><small>${it.type} · ×${it.qty}<br>${it.detail||''}</small>${it.action&&it.qty>0?`<button onclick="useItem(${i})">USAR</button>`:''}</div>`).join('')}</div><div class="row"><span>Fichas de trueque</span><b>◈ ${player.coins}</b></div><p>La carga elevada reduce la velocidad.</p>`}if(which==='journal'){$('#panelTitle').textContent='DIARIO DE CAMPO';c.innerHTML=`<div class="eyebrow">PRINCIPAL · ${quest.stage>=3?'COMPLETADA':'EN CURSO'}</div><h3 style="font:600 23px 'Barlow Condensed';margin:7px 0">${quest.active}</h3><p>${$('#questText').textContent}</p><div class="row"><span>1 · Sigue la señal de radio</span><b>${quest.stage>0?'✓':'…'}</b></div><div class="row"><span>2 · Explora el laboratorio X-12</span><b>${quest.stage>1?'✓':'—'}</b></div><div class="row"><span>3 · Regresa con Sokolov</span><b>${quest.stage>2?'✓':'—'}</b></div><div class="eyebrow">FACCIÓN · VIGÍAS</div><div class="row"><span>Reputación</span><b>${player.rep} · ${player.rep>30?'Aliado':'Neutral'}</b></div><p>Los Vigías protegen a Dubov. Los Mercaderes valoran artefactos y suministros.</p>`}if(which==='status'){$('#panelTitle').textContent='ESTADO DEL SUPERVIVIENTE';c.innerHTML=`<div class="row"><span>Salud</span><b>${Math.round(player.hp)}%</b></div><div class="row"><span>Hambre / Sed</span><b>${Math.round(player.food)}% / ${Math.round(player.water)}%</b></div><div class="row"><span>Radiación acumulada</span><b>${Math.round(player.rad)} mSv</b></div><div class="row"><span>Munición</span><b>${player.ammo} + ${player.reserve}</b></div><div class="row"><span>Reputación Vigías</span><b>${player.rep}</b></div><p>La fatiga aumenta al correr. Evita las anomalías sin detector.</p><button class="primary" onclick="saveGame()">GUARDAR PARTIDA</button>`}}
function closePanel(){$('#panel').classList.remove('open');paused=false;last=performance.now()}window.useItem=i=>{let it=inventory[i];if(!it||!it.qty)return;if(it.action==='food')player.food=clamp(player.food+28,0,100);if(it.action==='water')player.water=clamp(player.water+32,0,100);if(it.action==='med')player.hp=clamp(player.hp+45,0,100);it.qty--;if(it.qty<=0)inventory=inventory.filter(x=>x!==it);updateHud();renderPanel('inventory');playTone(360,.12)};
function drawGround(){ctx.fillStyle='#28382e';ctx.fillRect(0,0,W,H);for(let x=Math.floor(camera.x/70)*70;x<camera.x+W+70;x+=70)for(let y=Math.floor(camera.y/70)*70;y<camera.y+H+70;y+=70){ctx.fillStyle=Math.sin(x*12.98+y*4.14)%1>.5?'#2a3a2f':'#29382e';ctx.fillRect(x-camera.x,y-camera.y,70,70)}ctx.save();ctx.translate(-camera.x,-camera.y);ctx.lineCap='round';ctx.strokeStyle='#756f50';ctx.lineWidth=86;ctx.beginPath();ctx.moveTo(-100,1010);ctx.bezierCurveTo(450,900,520,1120,900,980);ctx.bezierCurveTo(1300,850,1320,670,1780,850);ctx.bezierCurveTo(2100,980,2270,880,2700,790);ctx.stroke();ctx.strokeStyle='#96906b';ctx.lineWidth=3;ctx.setLineDash([17,24]);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#40524699';for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse(850+i*90,1600-i*42,150,60,-.2,0,Math.PI*2);ctx.fill()}ctx.restore()}

