function near(){let all=[...lootObjects.filter(o=>!o.used).map(o=>({...o,kind:'object'})),...npcs.map(o=>({...o,kind:'npc'}))];all.sort((a,b)=>dist(player,a)-dist(player,b));return all.find(o=>dist(player,o)<75)}
function drawBuilding(b){let x=b.x-camera.x,y=b.y-camera.y;if(x<-260||x>W+260||y<-220||y>H+220)return;ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(x+b.w/2,y+b.h+10,b.w*.7,15,0,0,Math.PI*2);ctx.fill();if(b.type==='factory'){ctx.fillStyle='#5e6256';ctx.fillRect(x,y,b.w,b.h);ctx.fillStyle='#77786a';ctx.fillRect(x-6,y-9,b.w+10,18);ctx.fillStyle='#444b44';ctx.fillRect(x+12,y+19,40,40);ctx.fillRect(x+b.w-54,y+19,38,40);ctx.fillStyle='#a86448';ctx.fillRect(x+b.w*.48,y-40,25,40);ctx.fillStyle='#2d382f';ctx.fillRect(x+70,y+b.h-45,54,45)}else{ctx.fillStyle='#454a3f';ctx.fillRect(x,y+30,b.w,b.h-30);ctx.fillStyle=b.type==='hut'?'#565347':'#665947';ctx.beginPath();ctx.moveTo(x-12,y+38);ctx.lineTo(x+b.w*.5,y-14);ctx.lineTo(x+b.w+12,y+38);ctx.closePath();ctx.fill();ctx.fillStyle='#252d28';ctx.fillRect(x+b.w*.17,y+53,33,27);ctx.fillRect(x+b.w*.67,y+53,27,27);ctx.fillStyle='#302c25';ctx.fillRect(x+b.w*.43,y+b.h-43,34,43)}}function drawProps(){for(let p of props){let x=p.x-camera.x,y=p.y-camera.y;if(x<-60||x>W+60||y<-70||y>H+50)continue;if(p.type==='tree'){ctx.fillStyle='#0005';ctx.beginPath();ctx.ellipse(x+8,y+12,p.r*1.1,p.r*.48,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#514336';ctx.fillRect(x-3,y-1,7,18);ctx.fillStyle=p.tone>.5?'#374c37':'#3e513a';ctx.beginPath();ctx.arc(x,y-p.r*.35,p.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#506447';ctx.beginPath();ctx.arc(x-p.r*.28,y-p.r*.58,p.r*.66,0,Math.PI*2);ctx.fill()}else{ctx.fillStyle='#696d61';ctx.beginPath();ctx.ellipse(x,y,p.r,p.r*.68,-.3,0,Math.PI*2);ctx.fill()}}}function drawObject(o){let x=o.x-camera.x,y=o.y-camera.y;if(x<-40||x>W+40||y<-40||y>H+40)return;if(o.type==='anomaly'){let p=(Math.sin(performance.now()/400)+1)*.5;ctx.strokeStyle=`rgba(152,206,113,${.35+p*.5})`;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(x,y,28+p*10,13+p*5,0,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#d4ef76';ctx.fillRect(x-2,y-2,4,4)}else{ctx.fillStyle='#d4ef76';ctx.fillRect(x-5,y-5,10,10);ctx.strokeStyle='#d4ef76';ctx.strokeRect(x-8,y-8,16,16)}}
function drawActor(a,isPlayer=false){let x=a.x-camera.x,y=a.y-camera.y;if(x<-70||x>W+70||y<-70||y>H+70)return;ctx.fillStyle='#0008';ctx.beginPath();ctx.ellipse(x,y+11,11,5,0,0,Math.PI*2);ctx.fill();if(a.role==='enemy'){ctx.fillStyle='#705044';ctx.beginPath();ctx.ellipse(x,y,13,9,.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d47859';ctx.beginPath();ctx.arc(x+5,y-3,3,0,Math.PI*2);ctx.fill();return}ctx.fillStyle=isPlayer?'#b8b8a0':a.color;ctx.fillRect(x-7,y-10,14,16);ctx.fillStyle='#b49a7d';ctx.beginPath();ctx.arc(x,y-14,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#353b31';ctx.fillRect(x-8,y-2,16,6);if(isPlayer){ctx.fillStyle='#181d19';ctx.fillRect(x-3,y-3,20,3);ctx.fillStyle='#d4ef76';ctx.fillRect(x-2,y-19,4,3)}else if(dist(player,a)<150){ctx.fillStyle='#ecebdb';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText(a.name,x,y-27)}}

