function near(){let all=[...lootObjects.filter(o=>!o.used).map(o=>({...o,kind:'object'})),...npcs.map(o=>({...o,kind:'npc'}))];all.sort((a,b)=>dist(player,a)-dist(player,b));return all.find(o=>dist(player,o)<75)}
function updateHud(){for(let [id,v] of [['health',player.hp],['food',player.food],['water',player.water],['rad',player.rad]]){$('#'+id+'Bar').style.width=clamp(v,0,100)+'%';$('#'+id+'Val').textContent=String(Math.round(v)).padStart(2,'0')}$('#ammo').textContent=`${player.ammo} / ${player.reserve}`;let h=Math.floor(gameTime)%24,m=Math.floor(gameTime%1*60);$('#clock').textContent=`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')} · ${h<7?'AMANECER':h<18?'DÍA':h<20?'ATARDECER':'NOCHE'}`;$('#timeMini').textContent=String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');$('#weather').textContent=storm?'☂ LLUVIA FRÍA · 6°C':'☁ NIEBLA BAJA · 8°C';$('#weatherMini').textContent=storm?'LLUVIA · VIENTO 24':'VIENTO 12 KM/H';$('#weaponName').textContent=player.ammo?'AKM · 7.62':'AKM · VACÍO'}function blocked(x,y){return x<12||y<12||x>world.w-12||y>world.h-12||buildings.some(b=>x>b.x-12&&x<b.x+b.w+12&&y>b.y+8&&y<b.y+b.h)}function shoot(){if(fireCooldown>0)return;if(!player.ammo){notify('Sin munición cargada. Pulsa R para recargar.');return}player.ammo--;fireCooldown=.38;playTone(110,.09,'sawtooth',.045);let target=npcs.filter(n=>n.role==='enemy').sort((a,b)=>dist(player,a)-dist(player,b))[0],dx=target?target.x-player.x:Math.cos(aimAngle)*250,dy=target?target.y-player.y:Math.sin(aimAngle)*250,d=Math.hypot(dx,dy)||1;bullets.push({x:player.x,y:player.y-3,vx:dx/d*570,vy:dy/d*570,life:1.1})}
function update(dt){fireCooldown=Math.max(0,fireCooldown-dt);gameTime=(gameTime+dt*.012)%24;player.food=clamp(player.food-dt*.026,0,100);player.water=clamp(player.water-dt*.037,0,100);if(!player.food||!player.water)player.hp=clamp(player.hp-dt*1.3,0,100);if(player.rad>5)player.hp=clamp(player.hp-dt*(player.rad-5)*.018,0,100);let dx=0,dy=0;if(keys.w||keys.arrowup)dy--;if(keys.s||keys.arrowdown)dy++;if(keys.a||keys.arrowleft)dx--;if(keys.d||keys.arrowright)dx++;dx+=joy.x;dy+=joy.y;if(dx||dy){let l=Math.hypot(dx,dy);dx/=l;dy/=l;let sprint=keys.shift&&player.stamina>2,speed=sprint?225:150;if(sprint){player.stamina=clamp(player.stamina-dt*14,0,100);player.food=clamp(player.food-dt*.015,0,100)}else player.stamina=clamp(player.stamina+dt*9,0,100);let w=player.weight>25?.76:1,nx=player.x+dx*speed*w*dt,ny=player.y+dy*speed*w*dt;if(!blocked(nx,player.y))player.x=nx;if(!blocked(player.x,ny))player.y=ny;steps+=dt;if(steps>.4){steps=0;if(Math.random()<.25)playTone(76,.035,'triangle',.012)}}else player.stamina=clamp(player.stamina+dt*11,0,100);
for(let n of npcs){if(n.role==='enemy'){if(dist(player,n)<390){let d=dist(player,n)||1;n.x+=(player.x-n.x)/d*38*dt;n.y+=(player.y-n.y)/d*38*dt;if(d<24)player.hp=clamp(player.hp-dt*7,0,100)}else{n.x+=Math.sin(performance.now()/2200+n.baseX)*9*dt;n.y+=Math.cos(performance.now()/2600+n.baseY)*8*dt}}else{n.x=n.baseX+Math.sin(performance.now()/3900+n.baseX)*16;n.y=n.baseY+Math.cos(performance.now()/4300+n.baseY)*12}}for(let b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;for(let n of npcs)if(n.role==='enemy'&&dist(b,n)<19){n.role='dead';b.life=0;player.rep+=2;player.coins+=3;notify('AMENAZA NEUTRALIZADA · +3 fichas')}}bullets=bullets.filter(b=>b.life>0);for(let i=npcs.length-1;i>=0;i--)if(npcs[i].role==='dead')npcs.splice(i,1);let a=lootObjects.find(o=>o.type==='anomaly'&&!o.used);if(a&&dist(player,a)<100&&inventory.some(i=>i.name==='Detector de anomalías'))player.rad=clamp(player.rad+dt*.45,0,100);if(Math.random()<dt*.001)storm=!storm;if(player.hp<=0){player.hp=35;player.x=420;player.y=980;player.coins=Math.max(0,player.coins-10);notify('DESMAYO · despertaste en el perímetro. Perdiste 10 fichas.')}updateHud()}

