function loop(now=performance.now()){if(!running)return;let dt=Math.min(.05,Math.max(0,(now-last)/1000));last=now;if(!paused){update(dt);if(keys.space||fireHeld){if(fireCooldown<=0)shoot()}}render();requestAnimationFrame(loop)}
function reload(){if(player.ammo>=30){notify('El cargador ya está lleno.');return}if(player.reserve<=0){notify('No queda munición de reserva.');return}let amount=Math.min(30-player.ammo,player.reserve);player.ammo+=amount;player.reserve-=amount;playTone(220,.08,'triangle');notify('RECARGA · '+amount+' cartuchos')}
function togglePanel(which){if($('#dialog').classList.contains('open'))return;if($('#panel').classList.contains('open')){closePanel();return}panelOpen(which)}
