 let stick=$('#stick'),base=$('#joystick'),pointer=null;function moveStick(e){let r=base.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,l=Math.hypot(dx,dy),max=42;if(l>max){dx=dx/l*max;dy=dy/l*max}joy.x=dx/max;joy.y=dy/max;stick.style.transform=`translate(${dx}px,${dy}px)`}base.addEventListener('pointerdown',e=>{e.preventDefault();pointer=e.pointerId;base.setPointerCapture(pointer);moveStick(e)});base.addEventListener('pointermove',e=>{if(pointer===e.pointerId)moveStick(e)});function releaseStick(e){if(pointer!==null&&e.pointerId===pointer){pointer=null;joy.x=joy.y=0;stick.style.transform='translate(0,0)'}}base.addEventListener('pointerup',releaseStick);base.addEventListener('pointercancel',releaseStick);
